#!/usr/bin/env node
// Builds apps/worker/src/components.generated.ts from packages/components/<id>/component.json and the Luau
// files it lists, so the worker ships the exact component sources (no copies to keep in step by hand).
// `node scripts/generate/gen-components.mjs --check` exits 1 when the generated file is stale.
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const DIR = join(ROOT, 'packages', 'components');
const OUT = join(ROOT, 'apps', 'worker', 'src', 'components.generated.ts');

export function render() {
  const ids = readdirSync(DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(DIR, d.name, 'component.json')))
    .map((d) => d.name).sort();
  const components = {};
  for (const id of ids) {
    const contract = JSON.parse(readFileSync(join(DIR, id, 'component.json'), 'utf8'));
    if (contract.id !== id) throw new Error(`${id}/component.json has id ${contract.id}`);
    const files = Object.entries(contract.files ?? {}).map(([file, place]) => ({
      file, className: place.class, parent: place.parent, name: place.name,
      source: readFileSync(join(DIR, id, file), 'utf8'),
    }));
    components[id] = { contract, files };
  }
  return '// GENERATED by scripts/generate/gen-components.mjs from packages/components. Do not edit.\n' +
    '/* eslint-disable */\n' +
    'export interface ComponentFile { file: string; className: \'Script\' | \'LocalScript\' | \'ModuleScript\'; parent: string; name: string; source: string }\n' +
    'export interface Component { contract: Record<string, unknown> & { id: string; name: string; summary: string }; files: ComponentFile[] }\n' +
    `export const COMPONENTS: Record<string, Component> = ${JSON.stringify(components, null, 1)};\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = render();
  if (process.argv.includes('--check')) {
    const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
    if (current !== text) { console.error('components.generated.ts is stale: run node scripts/generate/gen-components.mjs'); process.exit(1); }
    console.log('components.generated.ts is current');
  } else {
    writeFileSync(OUT, text);
    console.log(`wrote ${OUT} (${text.length} bytes)`);
  }
}
